'use strict';

const EXPECTED_TASK_FIELD_TYPES = Object.freeze({
  recordId: 'string', recordType: 'string', rowRole: 'string', taskId: 'string', seriesId: 'string', occurrenceKey: 'string', tenantId: 'string', ownerUserId: 'string', telegramUserId: 'string', chatId: 'string', schemaVersion: 'string',
  taskKind: 'string', title: 'string', description: 'string', originalText: 'string', priority: 'number', tagsJson: 'string', parentTaskId: 'string', rootTaskId: 'string', sortOrder: 'number', requiredForParent: 'boolean', autoCompleteParent: 'boolean',
  scheduleKind: 'string', timeRole: 'string', dueDate: 'string', dueAt: 'string', windowStartAt: 'string', windowEndAt: 'string', preferredTimeOfDay: 'string', timezone: 'string', snoozedUntil: 'string',
  recurrenceRuleJson: 'string', recurrenceStartLocalDate: 'string', recurrenceEndLocalDate: 'string', nextOccurrenceAt: 'string', currentOccurrenceId: 'string', occurrenceScheduledFor: 'string', occurrenceOrdinal: 'number', seriesCompletedCount: 'number', seriesSkippedCount: 'number', seriesMissedCount: 'number', lastOccurrenceAt: 'string',
  reminderEnabled: 'boolean', reminderPolicyJson: 'string', reminderCursor: 'number', lastReminderAt: 'string', reminderCount: 'number', completionRequired: 'boolean', completionCheckAt: 'string', nextActionType: 'string', nextActionAt: 'string', actionSequence: 'number', actionToken: 'string', lastActionType: 'string', lastActionAt: 'string',
  status: 'string', statusReason: 'string', stateChangedAt: 'string', completedAt: 'string', terminalAt: 'string', completionNote: 'string', lastAnswerText: 'string', draftKind: 'string', pendingCommandJson: 'string', candidateTaskIdsJson: 'string', expectedAnswerType: 'string', correlationToken: 'string', askedMessageId: 'string', answerMessageId: 'string', answerExpiresAt: 'string', answerIdempotencyKey: 'string', telegramActionMessageId: 'string', telegramActionChatId: 'string', callbackScope: 'string',
  sourceUpdateId: 'string', sourceMessageId: 'string', sourceMessageDateIso: 'string', sourceInputType: 'string', idempotencyKey: 'string', rowVersion: 'number', lastMutationToken: 'string', leaseOwner: 'string', leaseUntil: 'string', dispatchToken: 'string', lastDeliveredActionToken: 'string', lastDeliveryOutcome: 'string', attemptCount: 'number', nextRetryAt: 'string', lastError: 'string', lastErrorAt: 'string', historyJson: 'string',
});

const registry = $items('Call | Chelsea Task Domain Runtime | Verify Folder User Identity | ProvisionTaskTable')[0]?.json || {};
const metadata = $input.first()?.json || {};
const expectedTableName = String(registry.taskTableName || '').trim();

function fail(reason) {
  return [{ json: {
    ...registry,
    _taskTableSchemaExact: false,
    taskHandled: true,
    taskOperation: 'task_table_schema_failed_review',
    taskErrorCode: 'task_table_schema_mismatch',
    taskSchemaFailureReason: String(reason || 'schema_mismatch').slice(0, 120),
    memoryWriteAllowed: false,
  } }];
}

try {
  if (metadata.error || metadata.statusCode >= 400) throw new Error('table_create_or_lookup_failed');
  if (!expectedTableName || String(metadata.name || '').trim() !== expectedTableName) throw new Error('table_name_mismatch');
  if (!String(metadata.id || '').trim()) throw new Error('table_id_missing');

  const columns = Array.isArray(metadata.columns)
    ? metadata.columns
    : (Array.isArray(metadata.columns?.column) ? metadata.columns.column : []);
  if (!columns.length) throw new Error('columns_missing');

  const actual = new Map();
  for (const column of columns) {
    const name = String(column?.name || '').trim();
    const type = String(column?.type || 'string').trim();
    if (!name) throw new Error('column_name_missing');
    if (actual.has(name)) throw new Error(`duplicate_column:${name}`);
    actual.set(name, type);
  }

  const expectedNames = Object.keys(EXPECTED_TASK_FIELD_TYPES);
  if (expectedNames.length !== 91) throw new Error('validator_field_count_mismatch');
  for (const name of expectedNames) {
    if (!actual.has(name)) throw new Error(`missing_column:${name}`);
    if (actual.get(name) !== EXPECTED_TASK_FIELD_TYPES[name]) throw new Error(`column_type_mismatch:${name}`);
  }

  // Data Table system fields are not custom schema columns in current n8n, but
  // tolerate them if a future API includes them in table metadata.
  const allowedSystemColumns = new Set(['id', 'createdAt', 'updatedAt']);
  for (const name of actual.keys()) {
    if (!Object.prototype.hasOwnProperty.call(EXPECTED_TASK_FIELD_TYPES, name) && !allowedSystemColumns.has(name)) {
      throw new Error(`unexpected_column:${name}`);
    }
  }

  return [{ json: {
    ...registry,
    _taskTableSchemaExact: true,
    taskTableId: String(metadata.id),
    taskTableSchemaFieldCount: expectedNames.length,
    memoryWriteAllowed: false,
  } }];
} catch (error) {
  return fail(error.message);
}

'use strict';
const input=$input.first()?.json||{};
const text=v=>String(v??'').normalize('NFKC').trim();
const username=v=>text(v).replace(/^@+/,'').toLowerCase();
const principalKey=text(input.principalKey);
const storageUsername=username(input.storageUsername||input.userId||input.memoryUserId);
const currentUsername=username(input.currentUsername||input.telegramUsername);
const telegramActorId=text(input.telegramActorId||input.telegramUserId);
if(!/^tgactor_[a-f0-9]{64}$/.test(principalKey))throw new Error('identity boundary: invalid principalKey');
if(!/^actor_[a-f0-9]{32}$/.test(storageUsername))throw new Error('identity boundary: invalid storageUsername');
if(!/^\d+$/.test(telegramActorId)||Number(telegramActorId)<=0)throw new Error('identity boundary: numeric Telegram actor required');
if(text(input.telegramActorId)&&text(input.telegramUserId)&&text(input.telegramActorId)!==text(input.telegramUserId))throw new Error('identity boundary: Telegram actor fields mismatch');
if(currentUsername&&!/^[a-z0-9_]{1,64}$/.test(currentUsername))throw new Error('identity boundary: invalid currentUsername');
const expected={userId:storageUsername,memoryUserId:storageUsername,tenantId:`tenant_${storageUsername}`,memoryTenantId:`tenant_${storageUsername}`,qdrantCollection:`kb_tenant_${storageUsername}`,soulId:`chelsea_soul_${storageUsername}`};
for(const [key,value] of Object.entries(expected)){if(text(input[key])!==value)throw new Error(`identity boundary: ${key} mismatch`);}
const schema=text(input.identitySchemaVersion);if(schema!=='chelsea_actor_identity_v3')throw new Error('identity boundary: schema mismatch');
if(input.identityAuthorityVerified!==true&&input.identityClaimsVerified!==true)throw new Error('identity boundary: PostgreSQL authority verification required');
return [{json:{...input,...expected,principalKey,storageUsername,currentUsername,telegramUsername:currentUsername,telegramActorId,telegramUserId:telegramActorId,identitySchemaVersion:schema,identityStatus:text(input.identityStatus)||'active',identityBoundaryVerified:true}}];
